const s=7,e="Chapter I: Basic Concepts of Complex Geometry",a=[{title:"Differentiable Manifolds",content:"A differentiable manifold M of dimension m and class Cᵏ is a topological space equipped with an atlas of homeomorphisms to ℝᵐ where transition maps are Cᵏ-differentiable.",formula:"\\tau_{\\alpha\\beta} = \\tau_\\alpha \\circ \\tau_\\beta^{-1} : \\tau_\\beta(U_\\alpha \\cap U_\\beta) \\to \\tau_\\alpha(U_\\alpha \\cap U_\\beta)"},{title:"Transition Maps",content:"The transition maps must be diffeomorphisms between open subsets of ℝᵐ, ensuring compatible coordinate systems across chart overlaps.",formula:null}],t={type:"torus",title:"The Torus as a Manifold",description:"The torus T² is a compact 2-dimensional manifold that can be covered by four coordinate charts. Rotate to see its global structure.",wireframe:!1},i=[{title:"General Relativity",field:"Physics",icon:"🌌",description:"Spacetime is modeled as a 4-dimensional differentiable manifold with Lorentzian metric.",examples:["Black hole horizons","Cosmological models","Gravitational waves"]},{title:"Robotics",field:"Engineering",icon:"🤖",description:"Configuration spaces of robotic systems are often non-Euclidean manifolds.",examples:["Robot arm kinematics","Motion planning","Mechanical linkages"]}],o={prerequisites:["Topology (open sets, continuity)","Multivariable calculus","Linear algebra"],concepts:[{name:"Atlas",definition:"A collection of charts {(Uα, τα)} covering M with compatible transition maps."},{name:"Chart",definition:"A pair (U, τ) where U ⊂ M is open and τ: U → V ⊂ ℝᵐ is a homeomorphism."}],exercises:[{question:"Show that the sphere S² requires at least two charts to be covered.",difficulty:"medium",hint:"Consider stereographic projection from north and south poles."},{question:"Prove that a single chart cannot cover a compact manifold of dimension ≥ 1.",difficulty:"hard",hint:"A single chart would embed M homeomorphically into ℝⁿ."}]},n={diagrams:[{type:"manifold",title:"Chart Overlap on S²",description:"Two stereographic charts covering the 2-sphere with overlap.",instructions:"The overlap region is shown in purple."}]},r={page:7,chapter:e,examples:a,simulator:t,applications:i,learning:o,interactive:n};export{i as applications,e as chapter,r as default,a as examples,n as interactive,o as learning,s as page,t as simulator};
